long long maxSubarray(std::vector<long long> nums) {
    long long best = nums[0];
    long long current = nums[0];
    for (std::size_t i = 1; i < nums.size(); ++i) {
        current = std::max(nums[i], current + nums[i]);
        best = std::max(best, current);
    }
    return best;
}

